class Records:
    def __init__(self, root, output):
        self.root, self.output, self.read, self.notes = root, output, {}, []

    def load(self, path, required=False):
        p = self.root / path
        if not p.exists():
            if required:
                raise Refusal("Required record missing: "+str(path))
            return {}
        try:
            record = json.loads(p.read_text())
        except (OSError, ValueError) as e:
            if required:
                raise Refusal(f"Required record unreadable: {path}: {e}") from e
            self.notes.append(f"Unreadable optional record: {path}");return {}
        self.read[str(p.relative_to(self.root))] = sha(p)
        return record

    def link(self, path, label=None):
        p = self.root / path
        if not p.exists():
            return esc(label or path)+" (pending)"
        href = quote(os.path.relpath(p, self.output.parent), safe="/._-")
        return '<a href="'+href+'">'+esc(label or path)+'</a>'

    def image(self, path, caption):
        if not (self.root / path).exists():
            return '<p>'+esc(caption)+': figure pending.</p>'
        href = quote(os.path.relpath(self.root / path, self.output.parent), safe="/._-")
        return f'<figure><img loading="lazy" src="{href}" alt="{esc(caption)}"><figcaption>{esc(caption)}</figcaption></figure>'


